CREATE TABLE IF NOT EXISTS evidence_record(node_id VARCHAR(64) NOT NULL,seq_no BIGINT NOT NULL,event_json JSON NOT NULL,chain_hash CHAR(64) NOT NULL,received_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(node_id,seq_no));
CREATE TABLE IF NOT EXISTS audit_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,node_id VARCHAR(64),result VARCHAR(32),detail VARCHAR(255));
CREATE TABLE IF NOT EXISTS collector_integrity_state(node_id VARCHAR(64) PRIMARY KEY,encrypted_state BLOB NOT NULL,last_sealed_seq BIGINT NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS collector_integrity_epoch(node_id VARCHAR(64) NOT NULL,epoch_no BIGINT NOT NULL,first_seq BIGINT NOT NULL,last_seq BIGINT NOT NULL,chain_head CHAR(64) NOT NULL,seal_tag CHAR(64) NOT NULL,received_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(node_id,epoch_no));
CREATE TABLE IF NOT EXISTS collector_integrity_checkpoint(node_id VARCHAR(64) NOT NULL,epoch_no BIGINT NOT NULL,seq_no BIGINT NOT NULL,chain_hash CHAR(64) NOT NULL,checkpoint_timestamp BIGINT NOT NULL,signature BLOB NOT NULL,received_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(node_id,epoch_no),UNIQUE KEY uq_collector_checkpoint_seq(node_id,seq_no));
